INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1324', '真夜中ハートチューン', '2026年冬', 'PR0056', 'TVシリーズ', 12, '『真夜中ハートチューン』（まよなかハートチューン、英: Finding the girl behind the voice.）は、五十嵐正邦による日本の漫画。『週刊少年マガジン』（講談社）において、2023年42号から連載中。略称は「マヨチュー」。男子高校生と放送部に所属する4人の女の子を描いたラブコメディ。千葉県千葉市美浜区が物語の舞台。', 187942) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1325', '勇者パーティーにかわいい子がいたので、告白してみた。', '2026年冬', 'PR0056', 'TVシリーズ', 13, '『勇者パーティーにかわいい子がいたので、告白してみた。』（ゆうしゃパーティーにかわいいこがいたので こくはくしてみた）は水星による日本のライトノベル。小説投稿サイト「小説家になろう」にて2013年7月17日より連載中。2014年10月からはモンスター文庫（双葉社）より書籍版が刊行されている。イラストはLa-naが担当。略称は「ゆうかわ」。 メディアミックスとして、海李によるコミカライズが同社の『マ', 195515) ON CONFLICT DO NOTHING;
