INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1382', 'あかね噺', '2026年春', 'PR0072', 'TVシリーズ', 12, '『あかね噺』（あかねばなし）は、原作：末永裕樹、作画：馬上鷹将による日本の漫画。『週刊少年ジャンプ』（集英社）において、2022年11号から連載中。落語家の父親を尊敬する少女が「真打」になるべく噺家として奮闘する女性落語家を描いた物語。2026年1月時点で累計発行部数300万部を突破している。', 196935) ON CONFLICT DO NOTHING;
