INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1393', '黒猫と魔女の教室', '2026年春', 'PR0058', 'TVシリーズ', NULL, '『黒猫と魔女の教室』（くろねことまじょのきょうしつ）は、金田陽介による日本の漫画。『マガジンポケット』（講談社）にて、2022年3月16日より連載中。師弟関係にある魔女見習いと黒猫による「学園ファンタジー」作品。 2026年4月よりテレビアニメが放送中。', 196974) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1394', '逃がした魚は大きかったが釣りあげた魚が大きすぎた件', '2026年春', 'PR0081', 'TVシリーズ', 12, '『逃がした魚は大きかったが釣りあげた魚が大きすぎた件』（にがしたさかなはおおきかったがつりあげたさかながおおきすぎたけん）は、ももよ万葉による日本のライトノベル。イラストは三登いつきが担当。「小説家になろう」にて短編小説として2020年10月にから掲載され、同年12月から2021年8月まで続編にあたる『続・逃がした魚は大きかったが釣りあげた魚が大きすぎた件』が同サイトで連載された。2021年8月よ', 201817) ON CONFLICT DO NOTHING;
