INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1420', 'きみが死ぬまで恋をしたい', '2026年夏', 'PR0084', 'TVシリーズ', NULL, '『きみが死ぬまで恋をしたい』（きみがしぬまでこいをしたい）は、あおのなちによる日本の漫画作品。略称は「きみ死ぬ」。『コミック百合姫』（一迅社）にて2018年10月号から2020年2月号まで連載された後（12話まで）、『ゆりひめ@ピクシブ』（同社）にて2020年1月より連載中。 孤児の少年少女に魔法を教え、兵器として育成する架空の養成学校を舞台としたダーク・ファンタジー作品であるとともに、そこで共同', 187260) ON CONFLICT DO NOTHING;
