INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1452', '鬼の花嫁 ', '2026年夏', 'PR0166', 'TVシリーズ', NULL, '『鬼の花嫁』（おにのはなよめ）は、クレハによる日本のライト文芸。イラストは白谷ゆうが担当している。2019年に投稿された短編『鬼の花嫁』を長編に書き直した作品で、当初の長編版の投稿タイトルは『鬼の花嫁は愛されたい』であったが、書籍化に伴い現在の形となった。書籍化が決定する前は「ノベマ!」の他に、「小説家になろう」、「アルファポリス」でも投稿していた。短編が「第1回ノベマ！キャラクター短編小説コンテ', 194219) ON CONFLICT DO NOTHING;
