INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH011291', 'AN1313', '天元', '天元（てんげん）  中国の自然観のひとつで、万物成育の源である、天の元気。 天子、君主のこと。 万物の素、元素（古代の意味での）。 天元術 - 中国・日本の数学技術。 算命学・四柱推命で天に配される十干（天干）の総称および別名。', NULL, NULL, 217291) ON CONFLICT DO NOTHING;
