INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH011619', 'AN1325', 'セシリア', 'セシリア (Cecilia) は、ヨーロッパ系の女性名。聖セシリアに由来する。 英語名ではシシーリア、スペイン語名ではセシーリアに近いが、この表記が用いられることが多い。英語名では異形にセシリー (Cecily) もある。イタリア語名のチェチーリア、ドイツ語名のツェツィーリアやツェツィーリエ、フランス語名のセシルなどに対応する。', NULL, '女性', 368609) ON CONFLICT DO NOTHING;
