INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH011753', 'AN1334', 'ゆう', 'ゆう、ユウ、Yu  夕、夕方。 夕部（せきぶ） - 漢字の部首。 木綿 (ゆう) - コウゾなどから作られる日本古来の繊維。 釉、釉薬 - 焼き物などの表面に使用する薬品。 日本語の動詞「言う（いう）」の誤記。現代仮名遣い（およびその許容）にも歴史的仮名遣にも該当しない。', NULL, '男性', 391359) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH011754', 'AN1334', '夜香ふうた', NULL, NULL, '男性', 393571) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH011755', 'AN1334', '鬼木羅だいち', NULL, NULL, '男性', 374530) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH011756', 'AN1334', '透綾アヤ', NULL, NULL, '女性', 388887) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH011757', 'AN1334', '毛馬内', '毛馬内、毛間内（けまない）は、秋田県の地名、またそれに由来する姓。  毛馬内町 - 鹿角郡に属した町。 毛馬内村 - 町村制以前の鹿角郡に属した村。他2村の村域と併せて毛馬内町が発足した。 十和田毛馬内 - 鹿角市の町字。かつての毛馬内町の一部。 毛馬内城 - 十和田毛馬内に存在した柏崎館の別称。 毛馬内駅 (曖昧さ回避) 毛馬内氏 - 武家の氏族。毛馬内を在所とした。', NULL, '男性', 391360) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH011758', 'AN1334', '夜香かおる', NULL, NULL, '男性', 393573) ON CONFLICT DO NOTHING;
