INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH012176', 'AN1363', 'ヤマハ', 'ヤマハ株式会社（英: YAMAHA CORPORATION）は、静岡県浜松市中央区に本社を置く、楽器や半導体、音響機器（オーディオ・ビジュアル）、スポーツ用品、自動車部品、ネットワーク機器の製造発売を手がける世界最大手の総合楽器・音響機器メーカー。 1969年にピアノ生産台数で世界一となり、販売額ベースで現在でも世界首位である。ほかの楽器でも、ハーモニカやリコーダー、ピアニカといった学校教材用から', NULL, '女性', 395407) ON CONFLICT DO NOTHING;
