INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH013260', 'AN1451', 'キックリ', 'キックリ（Kikkuli）は紀元前15世紀ごろのヒッタイトで戦闘用馬車を曳く馬匹を訓練していた人物。ミタンニの生まれ。1906年に土中から発見されたキックリ文書という粘土板にその名が記されている（#文書の発見とその内容）。文書に記された訓練の内容は現代の科学的な観点から見ても理に適ったものである（#馬匹訓練の再現実験）。', NULL, '男性', 35934) ON CONFLICT DO NOTHING;
