INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH013263', 'AN1451', 'カッシュ', 'カッシュは、ヨーロッパ系などの姓。原発音や由来は様々で、キャッシュと表記されることもあるのでそちらも参照。  ウリ・カッシュ - ドイツのヘヴィメタル系ドラマー。 ダニエル・カッシュ - カナダの俳優。 テレビアニメ『機動武闘伝Gガンダム』に登場する架空の人物。 ドモン・カッシュ - 主人公。 キョウジ・カッシュ - ドモンの兄。 ライゾウ・カッシュ、ミキノ・カッシュ - ドモンたち兄弟の父母。機', NULL, '男性', 51105) ON CONFLICT DO NOTHING;
